def seed_hr_people(apps, schema_editor):
    EmploymentType = apps.get_model("hrm", "EmploymentType")
    Department = apps.get_model("hrm", "Department")
    Employee = apps.get_model("hrm", "Employee")
    Numbering = apps.get_model("hrm", "EmployeeNumbering")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    Profile = apps.get_model("accounts", "UserProfile")

    for order, (name, code) in enumerate(
        [
            ("Full-time", "FULL_TIME"),
            ("Part-time", "PART_TIME"),
            ("Contract", "CONTRACT"),
            ("Probation", "PROBATION"),
            ("Intern", "INTERN"),
            ("Daily wage", "DAILY_WAGE"),
        ],
        start=1,
    ):
        EmploymentType.objects.get_or_create(
            code=code, defaults={"name": name, "is_active": True, "sort_order": order}
        )
    probation = EmploymentType.objects.filter(code="PROBATION").first()
    numbering, _ = Numbering.objects.get_or_create(
        pk=1, defaults={"prefix": "EMP-", "padding": 4, "last_number": 0}
    )

    departments = {}
    profiles = Profile.objects.select_related("user").filter(user__is_staff=True).order_by("user_id")
    for profile in profiles:
        label = (profile.department or "").strip()
        if not label or label in departments:
            continue
        existing = Department.objects.filter(name=label).first()
        if existing:
            departments[label] = existing
            continue
        code = "".join(ch for ch in label.upper() if ch.isalnum())[:24] or "DEPT"
        base = code
        n = 2
        while Department.objects.filter(code=code).exists():
            code = f"{base[:20]}-{n}"
            n += 1
        departments[label] = Department.objects.create(
            name=label,
            code=code,
            is_active=True,
            migrated_from_profile=True,
        )

    created = 0
    for profile in profiles:
        if Employee.objects.filter(user_id=profile.user_id).exists():
            continue
        raw_status = profile.employment_status or "active"
        status = raw_status if raw_status in {"resigned", "terminated", "inactive"} else "active"
        user = profile.user
        full_name = (f"{user.first_name} {user.last_name}").strip() or user.username
        numbering.last_number += 1
        code = f"{numbering.prefix}{numbering.last_number:0{numbering.padding}d}"
        employee = Employee(
            employee_code=code,
            full_name=full_name,
            phone=profile.phone or "",
            email=profile.personal_email or "",
            temporary_address=profile.temporary_address or "",
            permanent_address=profile.permanent_address or "",
            pan_vat_number=profile.pan_vat_number or "",
            citizenship_number=profile.citizenship_number or "",
            designation=profile.designation or "",
            department=departments.get((profile.department or "").strip()),
            employment_type=probation if raw_status == "probation" else None,
            joining_date=profile.join_date,
            date_of_birth=profile.date_of_birth,
            employment_status=status,
            status_effective_date=profile.join_date,
            emergency_contact_name=profile.emergency_contact_name or "",
            emergency_contact_phone=profile.emergency_contact_phone or "",
            dealer_id=profile.dealer_id,
            user_id=profile.user_id,
            migrated_from_profile=True,
        )
        if profile.photo:
            employee.photo = profile.photo.name
        employee.save()
        created += 1
    numbering.save(update_fields=["last_number"])


def unseed_hr_people(apps, schema_editor):
    Employee = apps.get_model("hrm", "Employee")
    Department = apps.get_model("hrm", "Department")
    Employee.objects.filter(migrated_from_profile=True).delete()
    Department.objects.filter(migrated_from_profile=True, employees__isnull=True).delete()


